 ModalData d;for(int k=0;k<3;++k){ModalMode m;m.mode_number=k+1;m.eigenvalue=1.0+k;m.frequency_hz=400.0+150*k;m.modal_mass=0.8+0.1*k;m.decay_time=3.0+k;m.inner_surface_harmonics={0,1,-1};m.outer_surface_harmonics={0,1,-1};for(int i=0;i<4;++i)for(int h=0;h<3;++h){double x=0.13*(i+1)*(h+2)*(k+1);m.inner_surface_fourier_radial.push_back(1e-4*std::sin(x));m.inner_surface_fourier_azimuthal.push_back(2e-5*std::cos(x));m.inner_surface_fourier_axial.push_back(2e-4*std::cos(x*0.7));m.outer_surface_fourier_radial.push_back(1e-4*std::cos(x));m.outer_surface_fourier_azimuthal.push_back(3e-5*std::sin(x));m.outer_surface_fourier_axial.push_back(2e-4*std::sin(x*0.8));}d.modes.push_back(std::move(m));}
